/**
 * Interactive Components JS
 *
 * Core behavior for all interactive component types generated by component-generators.ts:
 * - Flashcards: flip, navigate, keyboard support
 * - Sorting: reorder items, validate order
 * - Branching Scenario: scene navigation, restart
 * - Hotspot: show/close popups on image regions
 * - Case Study: toggle reveal of suggested analysis
 * - Simulation: multi-step option selection, scoring, restart
 * - Role-Play: dialogue turns, choice selection, restart
 *
 * All functions are exposed on `window` for use with inline onclick handlers.
 */
(function () {
  'use strict';

  // ================================================================
  // FLASHCARDS
  // ================================================================

  function flipCard(specId, index) {
    var card = document.getElementById('flashcard-' + specId + '-' + index);
    if (card) card.classList.toggle('flipped');
  }

  function nextCard(specId) {
    var container = document.querySelector('[data-spec-id="' + specId + '"]');
    if (!container) return;
    var current = parseInt(container.getAttribute('data-current-card') || '0');
    var total = parseInt(container.getAttribute('data-total-cards') || '0');
    if (current >= total - 1) return;
    var oldCard = document.getElementById('flashcard-' + specId + '-' + current);
    var newCard = document.getElementById('flashcard-' + specId + '-' + (current + 1));
    if (oldCard) { oldCard.classList.remove('active', 'flipped'); oldCard.style.display = 'none'; oldCard.setAttribute('aria-hidden', 'true'); oldCard.setAttribute('tabindex', '-1'); }
    if (newCard) { newCard.classList.add('active'); newCard.classList.remove('flipped'); newCard.style.display = ''; newCard.setAttribute('aria-hidden', 'false'); newCard.setAttribute('tabindex', '0'); newCard.focus(); }
    container.setAttribute('data-current-card', String(current + 1));
    var counter = document.getElementById('flashcards-counter-' + specId);
    if (counter) counter.textContent = 'Card ' + (current + 2) + ' of ' + total;
    var prev = container.querySelector('.flashcards-prev');
    var next = container.querySelector('.flashcards-next');
    if (prev) prev.disabled = false;
    if (next) next.disabled = (current + 1 >= total - 1);
  }

  function prevCard(specId) {
    var container = document.querySelector('[data-spec-id="' + specId + '"]');
    if (!container) return;
    var current = parseInt(container.getAttribute('data-current-card') || '0');
    var total = parseInt(container.getAttribute('data-total-cards') || '0');
    if (current <= 0) return;
    var oldCard = document.getElementById('flashcard-' + specId + '-' + current);
    var newCard = document.getElementById('flashcard-' + specId + '-' + (current - 1));
    if (oldCard) { oldCard.classList.remove('active', 'flipped'); oldCard.style.display = 'none'; oldCard.setAttribute('aria-hidden', 'true'); oldCard.setAttribute('tabindex', '-1'); }
    if (newCard) { newCard.classList.add('active'); newCard.classList.remove('flipped'); newCard.style.display = ''; newCard.setAttribute('aria-hidden', 'false'); newCard.setAttribute('tabindex', '0'); newCard.focus(); }
    container.setAttribute('data-current-card', String(current - 1));
    var counter = document.getElementById('flashcards-counter-' + specId);
    if (counter) counter.textContent = 'Card ' + current + ' of ' + total;
    var prev = container.querySelector('.flashcards-prev');
    var next = container.querySelector('.flashcards-next');
    if (next) next.disabled = false;
    if (prev) prev.disabled = (current - 1 <= 0);
  }

  function handleFlashcardKeydown(event, specId, index) {
    if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); flipCard(specId, index); }
    else if (event.key === 'ArrowRight' || event.key === 'ArrowDown') { event.preventDefault(); nextCard(specId); }
    else if (event.key === 'ArrowLeft' || event.key === 'ArrowUp') { event.preventDefault(); prevCard(specId); }
  }

  // ================================================================
  // SORTING
  // ================================================================

  function moveItemUp(specId, btn) {
    var item = btn.closest('.sorting-item');
    var prev = item.previousElementSibling;
    if (prev && prev.classList.contains('sorting-item')) {
      item.parentNode.insertBefore(item, prev);
      updateSortingNumbers(specId);
      item.focus();
    }
  }

  function moveItemDown(specId, btn) {
    var item = btn.closest('.sorting-item');
    var next = item.nextElementSibling;
    if (next && next.classList.contains('sorting-item')) {
      item.parentNode.insertBefore(next, item);
      updateSortingNumbers(specId);
      item.focus();
    }
  }

  function updateSortingNumbers(specId) {
    var list = document.getElementById('sorting-list-' + specId);
    if (!list) return;
    var items = list.querySelectorAll('.sorting-item');
    items.forEach(function (item, i) {
      var num = item.querySelector('.sorting-item-number');
      if (num) num.textContent = String(i + 1);
      var upBtn = item.querySelector('.sorting-btn-up');
      var downBtn = item.querySelector('.sorting-btn-down');
      if (upBtn) upBtn.disabled = (i === 0);
      if (downBtn) downBtn.disabled = (i === items.length - 1);
    });
  }

  function checkSortOrder(specId) {
    var list = document.getElementById('sorting-list-' + specId);
    var feedback = document.getElementById('sorting-feedback-' + specId);
    if (!list || !feedback) return;
    var items = list.querySelectorAll('.sorting-item');
    var allCorrect = true;
    var correctCount = 0;
    items.forEach(function (item, i) {
      var correctPos = parseInt(item.getAttribute('data-correct-position') || '0');
      var isCorrect = (correctPos === i + 1);
      item.classList.remove('sorting-correct', 'sorting-incorrect');
      item.classList.add(isCorrect ? 'sorting-correct' : 'sorting-incorrect');
      if (isCorrect) correctCount++; else allCorrect = false;
    });
    if (allCorrect) {
      feedback.innerHTML = '<p class="sorting-success">Excellent! All items are in the correct order.</p>';
      feedback.className = 'sorting-feedback sorting-feedback-correct';
    } else {
      feedback.innerHTML = '<p class="sorting-partial">' + correctCount + ' of ' + items.length + ' items are in the correct position. Keep trying!</p>';
      feedback.className = 'sorting-feedback sorting-feedback-incorrect';
    }
  }

  // ================================================================
  // BRANCHING SCENARIO
  // ================================================================

  function selectChoice(specId, nextSceneId, btn) {
    var wrapper = document.getElementById('branching-scenes-' + specId);
    if (!wrapper) return;
    // Show feedback briefly on the chosen button
    var fb = btn.querySelector('.branching-choice-feedback');
    if (fb) { fb.style.display = 'block'; fb.setAttribute('aria-hidden', 'false'); }
    // Transition after brief delay
    setTimeout(function () {
      var allScenes = wrapper.querySelectorAll('.branching-scene');
      allScenes.forEach(function (s) { s.classList.remove('active'); s.style.display = 'none'; s.setAttribute('aria-hidden', 'true'); });
      var nextScene = document.getElementById('scene-' + specId + '-' + nextSceneId);
      if (nextScene) { nextScene.classList.add('active'); nextScene.style.display = ''; nextScene.setAttribute('aria-hidden', 'false'); nextScene.focus(); }
    }, 800);
  }

  function restartScenario(specId) {
    var wrapper = document.getElementById('branching-scenes-' + specId);
    if (!wrapper) return;
    var allScenes = wrapper.querySelectorAll('.branching-scene');
    allScenes.forEach(function (s) { s.classList.remove('active'); s.style.display = 'none'; s.setAttribute('aria-hidden', 'true'); });
    // Reset all feedback displays
    wrapper.querySelectorAll('.branching-choice-feedback').forEach(function (fb) { fb.style.display = ''; fb.setAttribute('aria-hidden', 'true'); });
    var first = wrapper.querySelector('.branching-scene');
    if (first) { first.classList.add('active'); first.style.display = ''; first.setAttribute('aria-hidden', 'false'); first.focus(); }
  }

  // ================================================================
  // HOTSPOT
  // ================================================================

  function showHotspot(specId, hotspotId) {
    var container = document.querySelector('[data-spec-id="' + specId + '"]');
    if (!container) return;
    // Close any open popups first
    container.querySelectorAll('.hotspot-popup').forEach(function (p) { p.style.display = 'none'; });
    container.querySelectorAll('.hotspot-point').forEach(function (b) { b.setAttribute('aria-expanded', 'false'); b.classList.remove('active'); });
    // Open the selected popup
    var popup = document.getElementById('hotspot-popup-' + specId + '-' + hotspotId);
    var btn = container.querySelector('[aria-controls="hotspot-popup-' + specId + '-' + hotspotId + '"]');
    if (popup) { popup.style.display = 'block'; }
    if (btn) { btn.setAttribute('aria-expanded', 'true'); btn.classList.add('active'); }
  }

  function closeHotspot(specId) {
    var container = document.querySelector('[data-spec-id="' + specId + '"]');
    if (!container) return;
    container.querySelectorAll('.hotspot-popup').forEach(function (p) { p.style.display = 'none'; });
    container.querySelectorAll('.hotspot-point').forEach(function (b) { b.setAttribute('aria-expanded', 'false'); b.classList.remove('active'); });
  }

  // ================================================================
  // CASE STUDY
  // ================================================================

  function toggleCaseStudyAnalysis(specId) {
    var btn = document.getElementById('case-study-reveal-btn-' + specId);
    var panel = document.getElementById('case-study-analysis-' + specId);
    if (!btn || !panel) return;
    var isExpanded = btn.getAttribute('aria-expanded') === 'true';
    if (isExpanded) {
      panel.style.display = 'none';
      panel.setAttribute('aria-hidden', 'true');
      btn.setAttribute('aria-expanded', 'false');
      btn.querySelector('span').textContent = 'Reveal Suggested Analysis';
      btn.querySelector('.case-study-reveal-icon').style.transform = '';
    } else {
      panel.style.display = 'block';
      panel.setAttribute('aria-hidden', 'false');
      btn.setAttribute('aria-expanded', 'true');
      btn.querySelector('span').textContent = 'Hide Suggested Analysis';
      btn.querySelector('.case-study-reveal-icon').style.transform = 'rotate(180deg)';
      panel.focus();
    }
  }

  // ================================================================
  // SIMULATION
  // ================================================================

  function selectSimulationOption(specId, stepIndex, btn) {
    var step = document.getElementById('simulation-step-' + specId + '-' + stepIndex);
    if (!step) return;
    // Prevent re-selection
    if (step.getAttribute('data-answered') === 'true') return;
    step.setAttribute('data-answered', 'true');
    // Mark selected
    var allOpts = step.querySelectorAll('.simulation-option');
    allOpts.forEach(function (o) { o.setAttribute('aria-checked', 'false'); o.classList.remove('selected', 'correct', 'incorrect'); o.disabled = true; });
    btn.setAttribute('aria-checked', 'true');
    btn.classList.add('selected');
    var isCorrect = btn.getAttribute('data-correct') === 'true';
    btn.classList.add(isCorrect ? 'correct' : 'incorrect');
    // Highlight correct answer
    allOpts.forEach(function (o) { if (o.getAttribute('data-correct') === 'true') o.classList.add('correct'); });
    // Show feedback
    var feedbackEl = document.getElementById('simulation-feedback-' + specId + '-' + stepIndex);
    var feedbackText = btn.getAttribute('data-feedback');
    if (feedbackEl && feedbackText) {
      feedbackEl.innerHTML = '<p class="simulation-feedback-text">' + (isCorrect ? '<strong>Correct.</strong> ' : '<strong>Not quite.</strong> ') + feedbackText + '</p>';
      feedbackEl.style.display = 'block';
      feedbackEl.className = 'simulation-feedback ' + (isCorrect ? 'simulation-feedback-correct' : 'simulation-feedback-incorrect');
    }
    // Show next button
    var nextBtn = document.getElementById('simulation-next-btn-' + specId + '-' + stepIndex);
    if (nextBtn) { nextBtn.style.display = 'inline-flex'; nextBtn.focus(); }
    // Track score
    var container = document.querySelector('[data-spec-id="' + specId + '"]');
    if (container) {
      var score = parseInt(container.getAttribute('data-score') || '0');
      if (isCorrect) container.setAttribute('data-score', String(score + 1));
    }
  }

  function handleSimulationKeydown(event, specId, stepIndex, btn) {
    if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); selectSimulationOption(specId, stepIndex, btn); }
    else if (event.key === 'ArrowDown' || event.key === 'ArrowRight') {
      event.preventDefault();
      var next = btn.nextElementSibling;
      if (next && next.classList.contains('simulation-option')) next.focus();
    } else if (event.key === 'ArrowUp' || event.key === 'ArrowLeft') {
      event.preventDefault();
      var prev = btn.previousElementSibling;
      if (prev && prev.classList.contains('simulation-option')) prev.focus();
    }
  }

  function nextSimulationStep(specId, currentIndex) {
    var container = document.querySelector('[data-spec-id="' + specId + '"]');
    if (!container) return;
    var totalSteps = parseInt(container.getAttribute('data-total-steps') || '0');
    var currentStep = document.getElementById('simulation-step-' + specId + '-' + currentIndex);
    if (currentStep) { currentStep.style.display = 'none'; currentStep.setAttribute('aria-hidden', 'true'); currentStep.classList.remove('active'); }
    if (currentIndex + 1 >= totalSteps) {
      // Show summary
      var summary = document.getElementById('simulation-summary-' + specId);
      if (summary) { summary.style.display = ''; summary.setAttribute('aria-hidden', 'false'); summary.focus(); }
      var score = parseInt(container.getAttribute('data-score') || '0');
      var scoreEl = document.getElementById('simulation-score-' + specId);
      if (scoreEl) scoreEl.innerHTML = '<p>You answered <strong>' + score + ' of ' + totalSteps + '</strong> steps correctly.</p>';
      // Update progress bar to 100%
      var fill = container.querySelector('.simulation-progress-fill');
      if (fill) fill.style.width = '100%';
      var indicator = container.querySelector('.simulation-step-current');
      if (indicator) indicator.textContent = 'Complete';
    } else {
      var nextStep = document.getElementById('simulation-step-' + specId + '-' + (currentIndex + 1));
      if (nextStep) { nextStep.style.display = ''; nextStep.setAttribute('aria-hidden', 'false'); nextStep.classList.add('active'); nextStep.focus(); }
      container.setAttribute('data-current-step', String(currentIndex + 1));
      // Update progress
      var fill = container.querySelector('.simulation-progress-fill');
      if (fill) fill.style.width = (((currentIndex + 2) / totalSteps) * 100) + '%';
      var indicator = container.querySelector('.simulation-step-current');
      if (indicator) indicator.textContent = String(currentIndex + 2);
    }
  }

  function restartSimulation(specId) {
    var container = document.querySelector('[data-spec-id="' + specId + '"]');
    if (!container) return;
    var totalSteps = parseInt(container.getAttribute('data-total-steps') || '0');
    container.setAttribute('data-current-step', '0');
    container.setAttribute('data-score', '0');
    // Hide all steps and summary
    container.querySelectorAll('.simulation-step').forEach(function (s) { s.style.display = 'none'; s.setAttribute('aria-hidden', 'true'); s.classList.remove('active'); s.removeAttribute('data-answered'); });
    // Reset options
    container.querySelectorAll('.simulation-option').forEach(function (o) { o.classList.remove('selected', 'correct', 'incorrect'); o.setAttribute('aria-checked', 'false'); o.disabled = false; });
    // Reset feedback and next buttons
    container.querySelectorAll('.simulation-feedback').forEach(function (f) { f.style.display = 'none'; f.innerHTML = ''; });
    container.querySelectorAll('.simulation-next-btn').forEach(function (b) { b.style.display = 'none'; });
    // Show first step
    var first = document.getElementById('simulation-step-' + specId + '-0');
    if (first) { first.style.display = ''; first.setAttribute('aria-hidden', 'false'); first.classList.add('active'); first.focus(); }
    // Reset progress
    var fill = container.querySelector('.simulation-progress-fill');
    if (fill) fill.style.width = ((1 / totalSteps) * 100) + '%';
    var indicator = container.querySelector('.simulation-step-current');
    if (indicator) indicator.textContent = '1';
  }

  // ================================================================
  // ROLE-PLAY
  // ================================================================

  function nextRolePlayTurn(specId) {
    var container = document.querySelector('[data-spec-id="' + specId + '"]');
    if (!container) return;
    var current = parseInt(container.getAttribute('data-current-turn') || '0');
    var total = parseInt(container.getAttribute('data-total-turns') || '0');
    if (current >= total - 1) {
      // End of dialogue
      var contBtn = document.getElementById('roleplay-continue-btn-' + specId);
      var restartBtn = document.getElementById('roleplay-restart-btn-' + specId);
      if (contBtn) contBtn.style.display = 'none';
      if (restartBtn) { restartBtn.style.display = 'inline-flex'; restartBtn.focus(); }
      return;
    }
    var nextIndex = current + 1;
    var nextTurn = document.getElementById('roleplay-turn-' + specId + '-' + nextIndex);
    if (nextTurn) {
      nextTurn.style.display = '';
      nextTurn.setAttribute('aria-hidden', 'false');
      nextTurn.classList.add('visible');
      nextTurn.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
    container.setAttribute('data-current-turn', String(nextIndex));
    // Update progress
    var progress = document.getElementById('roleplay-progress-' + specId);
    if (progress) progress.querySelector('.roleplay-progress-text').textContent = 'Turn ' + (nextIndex + 1) + ' of ' + total;
    // If next turn is a choice, hide continue button until choice is made
    if (nextTurn && nextTurn.querySelector('.roleplay-choices')) {
      var contBtn = document.getElementById('roleplay-continue-btn-' + specId);
      if (contBtn) contBtn.style.display = 'none';
    }
    // If last turn, show restart instead
    if (nextIndex >= total - 1) {
      var contBtn = document.getElementById('roleplay-continue-btn-' + specId);
      if (contBtn) contBtn.style.display = 'none';
      var restartBtn = document.getElementById('roleplay-restart-btn-' + specId);
      if (restartBtn) restartBtn.style.display = 'inline-flex';
    }
  }

  function selectRolePlayChoice(specId, turnIndex, btn) {
    var turn = document.getElementById('roleplay-turn-' + specId + '-' + turnIndex);
    if (!turn || turn.getAttribute('data-chosen') === 'true') return;
    turn.setAttribute('data-chosen', 'true');
    // Highlight selected choice
    turn.querySelectorAll('.roleplay-choice-btn').forEach(function (b) { b.classList.remove('selected'); b.disabled = true; });
    btn.classList.add('selected');
    // Show feedback
    var feedbackText = btn.getAttribute('data-feedback');
    var feedbackEl = document.getElementById('roleplay-feedback-' + specId + '-' + turnIndex);
    if (feedbackEl && feedbackText) {
      feedbackEl.innerHTML = '<p>' + feedbackText + '</p>';
      feedbackEl.style.display = 'block';
    }
    // Show continue button
    var container = document.querySelector('[data-spec-id="' + specId + '"]');
    var current = parseInt(container.getAttribute('data-current-turn') || '0');
    var total = parseInt(container.getAttribute('data-total-turns') || '0');
    if (current < total - 1) {
      var contBtn = document.getElementById('roleplay-continue-btn-' + specId);
      if (contBtn) { contBtn.style.display = 'inline-flex'; contBtn.focus(); }
    } else {
      var restartBtn = document.getElementById('roleplay-restart-btn-' + specId);
      if (restartBtn) { restartBtn.style.display = 'inline-flex'; restartBtn.focus(); }
    }
  }

  function restartRolePlay(specId) {
    var container = document.querySelector('[data-spec-id="' + specId + '"]');
    if (!container) return;
    container.setAttribute('data-current-turn', '0');
    var total = parseInt(container.getAttribute('data-total-turns') || '0');
    // Hide all turns except first
    container.querySelectorAll('.roleplay-turn').forEach(function (t, i) {
      if (i === 0) { t.style.display = ''; t.setAttribute('aria-hidden', 'false'); t.classList.add('visible'); }
      else { t.style.display = 'none'; t.setAttribute('aria-hidden', 'true'); t.classList.remove('visible'); }
      t.removeAttribute('data-chosen');
    });
    // Reset choices
    container.querySelectorAll('.roleplay-choice-btn').forEach(function (b) { b.classList.remove('selected'); b.disabled = false; });
    container.querySelectorAll('.roleplay-choice-feedback').forEach(function (f) { f.style.display = 'none'; f.innerHTML = ''; });
    // Reset controls
    var contBtn = document.getElementById('roleplay-continue-btn-' + specId);
    var restartBtn = document.getElementById('roleplay-restart-btn-' + specId);
    if (contBtn) contBtn.style.display = (total > 1 ? 'inline-flex' : 'none');
    if (restartBtn) restartBtn.style.display = 'none';
    // Reset progress
    var progress = document.getElementById('roleplay-progress-' + specId);
    if (progress) progress.querySelector('.roleplay-progress-text').textContent = 'Turn 1 of ' + total;
  }

  // ================================================================
  // Expose all functions on window for onclick handlers
  // ================================================================
  window.flipCard = flipCard;
  window.nextCard = nextCard;
  window.prevCard = prevCard;
  window.handleFlashcardKeydown = handleFlashcardKeydown;
  window.moveItemUp = moveItemUp;
  window.moveItemDown = moveItemDown;
  window.updateSortingNumbers = updateSortingNumbers;
  window.checkSortOrder = checkSortOrder;
  window.selectChoice = selectChoice;
  window.restartScenario = restartScenario;
  window.showHotspot = showHotspot;
  window.closeHotspot = closeHotspot;
  window.toggleCaseStudyAnalysis = toggleCaseStudyAnalysis;
  window.selectSimulationOption = selectSimulationOption;
  window.handleSimulationKeydown = handleSimulationKeydown;
  window.nextSimulationStep = nextSimulationStep;
  window.restartSimulation = restartSimulation;
  window.nextRolePlayTurn = nextRolePlayTurn;
  window.selectRolePlayChoice = selectRolePlayChoice;
  window.restartRolePlay = restartRolePlay;
})();
